"""Reuse compiler-owned suites only with identical acceptance evidence and source."""
from hashlib import sha256
import json
from pathlib import Path
from infrastructure.utils.files import save_json


def acceptance_fingerprint(instructions, context, output):
    output=Path(output)
    paths=[output/'backend/tests/support/context.ts',output/'backend/scripts/test-api.mjs']
    for folder in ['backend/src/db/tables','backend/src/db/seeds']:
        paths.extend(sorted((output/folder).glob('*.sql')))
    evidence={str(p.relative_to(output)):sha256(p.read_bytes()).hexdigest() for p in paths if p.is_file()}
    return sha256(json.dumps({'version':1,'instructions':instructions,'context':context,'fixtures':evidence},
        sort_keys=True,ensure_ascii=False).encode()).hexdigest()


def suite_path(output, relative):
    if not isinstance(relative,str) or not relative.startswith('backend/tests/') or not relative.endswith('.ts'):
        return None
    output=Path(output).resolve();path=output/relative
    if not path.is_file() or not path.resolve().is_relative_to(output):return None
    current=output
    for part in Path(relative).parts:
        current=current/part
        if current.is_symlink():return None
    return path


def reusable_suite(output, aid, fingerprint, relative):
    """An old GREEN is never evidence: caller must still execute its fresh gate."""
    try:
        record=json.loads((Path(output)/'.arc/backend_acceptance_cache.json').read_text())[aid]
        path=suite_path(output,relative)
        return bool(path and record['fingerprint']==fingerprint and record['path']==relative
            and record['sha256']==sha256(path.read_bytes()).hexdigest())
    except (OSError,ValueError,KeyError,TypeError):return False


def remember_suite(output, aid, fingerprint, relative):
    path=suite_path(output,relative)
    if not path:return
    target=Path(output)/'.arc/backend_acceptance_cache.json'
    try:
        records=json.loads(target.read_text())
        if not isinstance(records,dict):records={}
    except (OSError,ValueError):records={}
    records[aid]={'fingerprint':fingerprint,'path':relative,'sha256':sha256(path.read_bytes()).hexdigest()}
    save_json(target,records)
"""Reserve the maximum charge for each request before sending it."""

from contextlib import contextmanager
from contextvars import ContextVar
from decimal import Decimal, InvalidOperation
from hashlib import sha256
import json
import os
from pathlib import Path

from infrastructure.utils.files import save_json


_meter = ContextVar("arc_model_spend", default=None)
_MILLION = Decimal(1_000_000)


class ModelSpendLimitReached(Exception):
    """The configured budget cannot safely fund another request."""


def _money(value):
    try:
        amount = Decimal(str(value))
    except InvalidOperation as error:
        raise ValueError(f"Invalid monetary value: {value!r}") from error
    if not amount.is_finite() or amount < 0:
        raise ValueError("Monetary values must be finite and nonnegative")
    return amount


def _positive_int(value):
    if type(value) is not int or value <= 0:
        raise ValueError("Model token limits must be positive integers")
    return value


@contextmanager
def _exclusive(ledger):
    """One compiler owns the ledger while it can submit model requests."""
    lock = ledger.with_suffix(ledger.suffix + ".lock")
    lock.parent.mkdir(parents=True, exist_ok=True)
    with lock.open("a+b") as stream:
        try:
            if os.name == "nt":
                import msvcrt
                stream.seek(0)
                msvcrt.locking(stream.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError as error:
            raise ValueError(f"Model budget ledger is already in use: {ledger}") from error
        yield


class SpendMeter:
    def __init__(self, limit, rate_card, ledger):
        self.limit = _money(limit)
        if not self.limit:
            raise ValueError("The model budget must be positive")
        self.ledger = Path(ledger).resolve()
        raw = Path(rate_card).read_bytes()
        self.rate_digest = sha256(raw).hexdigest()
        self.rates = {}
        for model, entry in json.loads(raw).items():
            self.rates[model] = {
                "input": _money(entry["input_cny_per_million"]),
                "cached": _money(entry.get("cached_input_cny_per_million", entry["input_cny_per_million"])),
                "output": _money(entry["output_cny_per_million"]),
                "fee": _money(entry.get("request_cny", 0)),
                "max_input": _positive_int(entry["max_input_tokens"]),
                "max_output": _positive_int(entry["max_output_tokens"]),
            }
        if not self.rates:
            raise ValueError("The model rate card cannot be empty")
        self.spent = Decimal(0)
        self.calls = 0
        self.unsettled = 0
        self.invalid_usage = False

    def restore(self):
        if not self.ledger.is_file():
            self.publish()
            return
        data = json.loads(self.ledger.read_text(encoding="utf-8"))
        if _money(data["limit_cny"]) != self.limit or data["rate_card_sha256"] != self.rate_digest:
            raise ValueError("The existing budget ledger uses a different rate card or limit")
        self.spent = _money(data["reserved_or_spent_cny"])
        self.calls = data["requests_reserved"]
        self.unsettled = data["unsettled_requests"]
        self.invalid_usage = data["provider_usage_outside_reservation"]

    def publish(self):
        save_json(self.ledger, {"limit_cny": str(self.limit), "rate_card_sha256": self.rate_digest,
            "reserved_or_spent_cny": str(self.spent), "requests_reserved": self.calls,
            "unsettled_requests": self.unsettled, "provider_usage_outside_reservation": self.invalid_usage})

    def reserve(self, arguments):
        model = arguments["model"]
        if self.invalid_usage or self.spent > self.limit:
            raise ModelSpendLimitReached("Model usage exceeded a verified limit in the rate card")
        if model not in self.rates:
            raise ModelSpendLimitReached(f"No verified billing limits configured for model {model}")
        if arguments.get("n", 1) != 1 or {"max_tokens", "max_completion_tokens"} <= arguments.keys():
            raise ModelSpendLimitReached("Budgeted requests must use one response and one output token limit")
        rate = self.rates[model]
        output_field = "max_tokens" if "max_tokens" in arguments else "max_completion_tokens"
        output_limit = min(_positive_int(arguments.get(output_field, rate["max_output"])), rate["max_output"])
        arguments[output_field] = output_limit
        reserve = rate["fee"] + (rate["max_input"] * max(rate["input"], rate["cached"])
            + output_limit * rate["output"]) / _MILLION
        if self.spent + reserve > self.limit:
            raise ModelSpendLimitReached(
                f"Next request reserves ¥{reserve}, with ¥{self.limit - self.spent} available")
        self.spent += reserve
        self.calls += 1
        self.unsettled += 1
        self.publish()
        return reserve, rate, output_limit

    def settle(self, reservation, usage):
        reserve, rate, output_limit = reservation
        prompt, output, cached = usage.get("Input"), usage.get("Output"), usage.get("Cached input")
        if type(prompt) is not int or type(output) is not int or min(prompt, output) < 0:
            return  # Keep the full reservation when the provider reports no usable counts.
        if type(cached) is not int or not 0 <= cached <= prompt:
            input_charge = prompt * max(rate["input"], rate["cached"])
        else:
            input_charge = cached * rate["cached"] + (prompt - cached) * rate["input"]
        actual = rate["fee"] + (input_charge + output * rate["output"]) / _MILLION
        self.spent += actual - reserve
        self.unsettled -= 1
        self.invalid_usage |= prompt > rate["max_input"] or output > output_limit or actual > reserve
        self.publish()
        if self.invalid_usage:
            raise ModelSpendLimitReached("Provider returned usage outside the configured billing limits")


def current_meter():
    return _meter.get()


@contextmanager
def configured_spend_budget():
    limit, card, ledger = (os.getenv(key) for key in (
        "ARC_MODEL_BUDGET_CNY", "ARC_MODEL_RATE_CARD", "ARC_MODEL_LEDGER"))
    if not any((limit, card, ledger)):
        yield
        return
    if not all((limit, card, ledger)):
        raise ValueError("Set ARC_MODEL_BUDGET_CNY, ARC_MODEL_RATE_CARD and ARC_MODEL_LEDGER together")
    meter = SpendMeter(limit, card, ledger)
    with _exclusive(meter.ledger):
        meter.restore()
        token = _meter.set(meter)
        try:
            yield
        finally:
            _meter.reset(token)
"""Coarse API RAG over descriptions and field-level read/write obligations."""

from copy import deepcopy
from infrastructure.shared.rag.bm25 import rank


class ApiRetriever:
    """Coarse retrieval adapter for reusable canonical API Primitives."""
    def retrieve(self, query: str, apis: dict, top_k: int = 6) -> dict:
        # --- Extension point: semantic API reuse ------------------------------
        # Replace lexical relevance with embeddings, reranking, or a graph of
        # reusable operations. Retrieval never changes existing API identities.
        """Rank API descriptions and read/write symbols, returning hits and copies of the selected API definitions."""
        documents = {
            key: f"{key} {api['description']} {' '.join(api['read'])} {' '.join(api['write'])}"
            for key, api in apis.items()
        }
        matches = rank(query, documents, top_k)
        return {"matches": matches, "apis": {item["symbol"]: deepcopy(apis[item["symbol"]]) for item in matches}}
"""Page-first lexical retrieval returning complete canonical UI/data subtrees."""

import json

from infrastructure.stages.frontend.ui.design import page_context
from infrastructure.shared.rag.bm25 import rank


class PageRetriever:
    """Page-first retrieval adapter that returns complete reusable UI/data subtrees."""
    def retrieve(self, requirement: dict, design: dict, top_k: int = 3) -> dict:
        """Select explicit page/image matches plus lexical hits, returning each page with its complete UI/data subtree."""
        hints = {image.get("page") for image in requirement["images"].values() if image.get("page")}
        evidence = requirement["description"] + "\n" + json.dumps(requirement["steps"], ensure_ascii=False)
        explicit = [pid for pid, page in design["pages"].items() if pid in hints or page["name"] in hints
            or set(page["images"]) & set(requirement["images"])
            or (page["route"] != "/" and page["route"] in evidence)]
        documents = {pid: json.dumps({"id": pid, **page}, ensure_ascii=False) for pid, page in design["pages"].items()}
        local_requirement = {key: value for key, value in requirement.items() if key != "application_requirements"}
        matches = rank(json.dumps(local_requirement, ensure_ascii=False), documents, top_k)
        selected = list(dict.fromkeys([*explicit, *(item["symbol"] for item in matches)]))
        return {"explicit_matches": explicit, "matches": matches,
            "pages": {pid: page_context(design, pid) for pid in selected}}
